	(202, 98, '_wp_attached_file', '2026/02/Deepak.jpg'),
	(203, 98, '_wp_attachment_metadata', 'a:6:{s:5:"width";i:854;s:6:"height";i:918;s:4:"file";s:18:"2026/02/Deepak.jpg";s:8:"filesize";i:107330;s:5:"sizes";a:3:{s:6:"medium";a:5:{s:4:"file";s:18:"Deepak-279x300.jpg";s:5:"width";i:279;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";s:8:"filesize";i:11979;}s:9:"thumbnail";a:5:{s:4:"file";s:18:"Deepak-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";s:8:"filesize";i:4816;}s:12:"medium_large";a:5:{s:4:"file";s:18:"Deepak-768x826.jpg";s:5:"width";i:768;s:6:"height";i:826;s:9:"mime-type";s:10:"image/jpeg";s:8:"filesize";i:59012;}}s:10:"image_meta";a:12:{s:8:"aperture";s:1:"0";s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";s:1:"0";s:9:"copyright";s:0:"";s:12:"focal_length";s:1:"0";s:3:"iso";s:1:"0";s:13:"shutter_speed";s:1:"0";s:5:"title";s:0:"";s:11:"orientation";s:1:"1";s:8:"keywords";a:0:{}}}'),
	(204, 97, '_thumbnail_id', '98'),
	(205, 97, '_team_position', 'Director - Finance & Taxation'),
	(206, 97, '_team_email', ''),
	(207, 97, '_team_phone', ''),
	(208, 97, '_team_about', 'Deepak Gupta ist ein indischer Chartered Accountant mit mehr als 16 Jahren Erfahrung in der Beratung europäischer Unternehmen zu finanziellen, steuerlichen und regulatorischen Aspekten ihrer Aktivitäten in Indien. Seine Kernkompetenzen liegen in internationaler Besteuerung, grenzüberschreitenden Transaktionen, Transfer Pricing, Finanzstrukturierung und regulatorischer Compliance. Bei FeBoKo arbeitet er eng mit der europäischen Unternehmensführung sowie den indischen Tochtergesellschaften zusammen und leitet ausgelagerte Finanzfunktionen.'),
	(209, 97, '_team_about_en', 'Deepak Gupta is an Indian Chartered Accountant with more than 16 years of experience advising European companies on financial, taxation, and regulatory aspects of their India operations. His core areas of expertise include international taxation, cross-border transactions, transfer pricing, financial structuring, and regulatory compliance. At FeBoKo, he works closely with clients’ European leadership and Indian subsidiaries while leading outsourced finance functions.'),
	(210, 99, '_edit_lock', '1777325330:4'),
	(211, 99, '_edit_last', '4'),
	(212, 100, '_wp_attached_file', '2026/02/Shekhar-Sharma-2.png'),
	(213, 100, '_wp_attachment_metadata', 'a:6:{s:5:"width";i:794;s:6:"height";i:794;s:4:"file";s:28:"2026/02/Shekhar-Sharma-2.png";s:8:"filesize";i:610810;s:5:"sizes";a:3:{s:6:"medium";a:5:{s:4:"file";s:28:"Shekhar-Sharma-2-300x300.png";s:5:"width";i:300;s:6:"height";i:300;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:84007;}s:9:"thumbnail";a:5:{s:4:"file";s:28:"Shekhar-Sharma-2-150x150.png";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:27360;}s:12:"medium_large";a:5:{s:4:"file";s:28:"Shekhar-Sharma-2-768x768.png";s:5:"width";i:768;s:6:"height";i:768;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:334662;}}s:10:"image_meta";a:12:{s:8:"aperture";s:1:"0";s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";s:1:"0";s:9:"copyright";s:0:"";s:12:"focal_length";s:1:"0";s:3:"iso";s:1:"0";s:13:"shutter_speed";s:1:"0";s:5:"title";s:0:"";s:11:"orientation";s:1:"0";s:8:"keywords";a:0:{}}}'),
	(214, 99, '_thumbnail_id', '100'),
	(215, 99, '_team_position', 'Manager Controlling & Advisory'),
	(216, 99, '_team_email', ''),
	(217, 99, '_team_phone', ''),
	(218, 99, '_team_about', 'Als qualifizierter Chartered Accountant verfügt Shekhar Sharma über mehr als acht Jahre Erfahrung in der Steuer- und Unternehmensberatung für nationale und internationale Unternehmen. Seine Expertise umfasst Transfer-Pricing-Dokumentation, SVB-Verfahren, steuerliche Beratung, interne Kontrollsysteme, Due-Diligence-Prüfungen sowie Beratung bei Unternehmensgründungen. Bei FeBoKo unterstützt er Mandanten dabei, steuerliche Risiken zu steuern, Strukturen zu optimieren und regulatorische Anforderungen zuverlässig einzuhalten.'),
	(219, 99, '_team_about_en', 'As a qualified Chartered Accountant, Shekhar Sharma has over Eight years of experience in tax and business consulting for domestic and international companies. His expertise includes transfer pricing documentation, SVB procedures, tax advisory, internal controls, due diligence, and company formation advisory. At FeBoKo, he supports clients in managing tax risks, optimizing structures, and ensuring regulatory compliance.'),
	(220, 101, '_edit_lock', '1777325320:4'),
	(221, 101, '_edit_last', '4'),
	(222, 102, '_wp_attached_file', '2026/02/Shubham-Kumar-2.png'),
	(223, 102, '_wp_attachment_metadata', 'a:6:{s:5:"width";i:1380;s:6:"height";i:678;s:4:"file";s:27:"2026/02/Shubham-Kumar-2.png";s:8:"filesize";i:524829;s:5:"sizes";a:4:{s:6:"medium";a:5:{s:4:"file";s:27:"Shubham-Kumar-2-300x147.png";s:5:"width";i:300;s:6:"height";i:147;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:36873;}s:5:"large";a:5:{s:4:"file";s:28:"Shubham-Kumar-2-1024x503.png";s:5:"width";i:1024;s:6:"height";i:503;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:282604;}s:9:"thumbnail";a:5:{s:4:"file";s:27:"Shubham-Kumar-2-150x150.png";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:29626;}s:12:"medium_large";a:5:{s:4:"file";s:27:"Shubham-Kumar-2-768x377.png";s:5:"width";i:768;s:6:"height";i:377;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:174108;}}s:10:"image_meta";a:12:{s:8:"aperture";s:1:"0";s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";s:1:"0";s:9:"copyright";s:0:"";s:12:"focal_length";s:1:"0";s:3:"iso";s:1:"0";s:13:"shutter_speed";s:1:"0";s:5:"title";s:0:"";s:11:"orientation";s:1:"0";s:8:"keywords";a:0:{}}}'),
	(224, 101, '_thumbnail_id', '102'),
	(225, 101, '_team_position', 'Consultant Finance & Taxation'),
	(226, 101, '_team_email', ''),
	(227, 101, '_team_phone', ''),
	(228, 101, '_team_about', 'Shubham Kumar ist ein Finanzexperte mit einem Masterabschluss und über vier Jahren Erfahrung in der Beratung europäischer Kunden zu Steuerfragen, Rechnungslegung und grenzüberschreitenden Transaktionen. Seine Erfahrung umfasst indirekte und direkte Steuern, Transfer Pricing, gesetzliche Abschlussprüfungen, GAAP-basierte Buchhaltung sowie die Betreuung von Steuerprüfungen und Einspruchsverfahren. Bei FeBoKo unterstützt er Mandanten bei Steuer-Compliance, Finanzberichterstattung und regulatorischer Beratung.'),
	(229, 101, '_team_about_en', 'Shubham Kumar is a finance professional with a Master’s degree and over four years of experience advising European clients on taxation, accounting, and cross-border transactions. His experience spans indirect and direct taxation, transfer pricing, statutory audits, GAAP-based accounting, and handling tax audits and appeals. At FeBoKo, he supports clients with tax compliance, financial reporting, and regulatory advisory.'),
	(230, 103, '_edit_lock', '1777325308:4'),
	(231, 103, '_edit_last', '4'),
	(232, 104, '_wp_attached_file', '2026/02/sarita.png'),
	(233, 104, '_wp_attachment_metadata', 'a:6:{s:5:"width";i:378;s:6:"height";i:496;s:4:"file";s:18:"2026/02/sarita.png";s:8:"filesize";i:138768;s:5:"sizes";a:2:{s:6:"medium";a:5:{s:4:"file";s:18:"sarita-229x300.png";s:5:"width";i:229;s:6:"height";i:300;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:48329;}s:9:"thumbnail";a:5:{s:4:"file";s:18:"sarita-150x150.png";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:9:"image/png";s:8:"filesize";i:20610;}}s:10:"image_meta";a:12:{s:8:"aperture";s:1:"0";s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";s:1:"0";s:9:"copyright";s:0:"";s:12:"focal_length";s:1:"0";s:3:"iso";s:1:"0";s:13:"shutter_speed";s:1:"0";s:5:"title";s:0:"";s:11:"orientation";s:1:"0";s:8:"keywords";a:0:{}}}'),
	(234, 103, '_thumbnail_id', '168'),
	(235, 103, '_team_position', 'Manager Legal Affairs & Corporate Governance'),
	(236, 103, '_team_email', ''),
	(237, 103, '_team_phone', ''),
	(238, 103, '_team_about', 'Sarita Bhatt ist Company Secretary und Juristin mit über 10 Jahren Erfahrung in den Bereichen Corporate Governance, regulatorische Compliance und Rechtsberatung. Sie berät Unternehmen zu gesellschaftsrechtlichen und sekretariellen Themen, zu Vorschriften für ausländische Investitionen sowie zu Unternehmensstrukturen und unterstützt Firmen dabei, stabile Governance-Strukturen aufzubauen und komplexe regulatorische Anforderungen zu erfüllen.\r\nSie ist bekannt für ihren analytischen Ansatz, ihr ausgeprägtes regulatorisches Verständnis und ihre Fähigkeit, praxisnahe sowie wirtschaftsorientierte rechtliche Lösungen zu entwickeln.'),
	(239, 103, '_team_about_en', 'Sarita Bhatt is a Company Secretary and Lawyer with over 10 years of experience in corporate governance, regulatory compliance, and legal advisory. She advises companies on secretarial matters, foreign investment regulations, and corporate structuring, helping businesses maintain strong governance frameworks and meet complex regulatory requirements.\r\nShe is recognized for her analytical approach, strong regulatory understanding, and ability to provide practical and business-oriented legal solutions.'),
	(240, 105, '_edit_lock', '1777325297:4'),
	(241, 105, '_edit_last', '4'),
	(242, 106, '_wp_attached_file', '2026/02/TW_halb_quad.jpg'),
