	(337, 138, '_form', '<div class="cf7-row">\n<label> Vorname\n    [text* your-first-name akismet:author autocomplete:given-name placeholder "Vorname eingeben"]\n</label>\n\n<label> Nachname\n    [text* your-last-name autocomplete:family-name placeholder "Nachname eingeben"]\n</label>\n</div>\n\n<div class="cf7-row">\n<label> Email\n    [email* your-email akismet:author_email autocomplete:email placeholder "Email eingeben"]\n</label>\n\n<label> Ihr Betreff\n    [text* your-subject placeholder "Betreff eingeben"]\n</label>\n</div>\n\n<label> Ihre Nachricht\n    [textarea* your-message akismet:body placeholder "Ihre Nachricht an uns"]\n</label>\n\n[acceptance acceptance-969] \nIch akzeptiere die <a href="/datenschutz" target="_blank">Datenschutzerklärung</a>.\n[/acceptance]\n\n[submit "Nachricht absenden"]'),
	(338, 138, '_mail', 'a:9:{s:6:"active";b:1;s:7:"subject";s:30:"[_site_title] "[your-subject]"";s:6:"sender";s:36:"[_site_title] <wordpress@feboko.com>";s:9:"recipient";s:15:"info@feboko.com";s:4:"body";s:233:"Von: [your-first-name] [your-last-name] ([your-email])\nBetreff: [your-subject]\n\nNachricht:\n[your-message]\n\n-- \nDies ist eine Benachrichtigung, dass ein Kontaktformular auf Ihrer Website abgeschickt wurde. ([_site_title] [_site_url]).";s:18:"additional_headers";s:22:"Reply-To: [your-email]";s:11:"attachments";s:0:"";s:8:"use_html";b:1;s:13:"exclude_blank";b:1;}'),
	(339, 138, '_mail_2', 'a:9:{s:6:"active";b:1;s:7:"subject";s:31:"Vielen Dank für Ihre Nachricht";s:6:"sender";s:31:"[_site_title] <info@feboko.com>";s:9:"recipient";s:12:"[your-email]";s:4:"body";s:182:"Hallo [your-first-name] [your-last-name],\n\nIhre Nachricht "[your-subject]", ist erfolgreich bei uns eingangen.\n\nWir werden uns bald bei Ihnen melden.\n\n\nViele Grüße,\ndas FeBoKo Team";s:18:"additional_headers";s:25:"Reply-To: info@feboko.com";s:11:"attachments";s:0:"";s:8:"use_html";b:0;s:13:"exclude_blank";b:0;}'),
