	(344, 139, '_form', '<div class="cf7-row">\n<label> First Name\n    [text* your-first-name akismet:author autocomplete:given-name placeholder "Enter First Name"]\n</label>\n\n<label> Last Name\n    [text* your-last-name akismet:author autocomplete:family-name placeholder "Enter Last Name"]\n</label>\n</div>\n\n<div class="cf7-row">\n<label> Email\n    [email* your-email akismet:author_email autocomplete:email placeholder "Enter Email"]\n</label>\n\n<label> Your Subject\n    [text* your-subject placeholder "Enter Subject"]\n</label>\n</div>\n\n<label> Your Message\n    [textarea* your-message akismet:body placeholder "Your Message to us"]\n</label>\n\n[acceptance acceptance-969 use_label_element]\nI accept the <a href="/datenschutz" target="_blank">Privacy Policy</a>.\n[/acceptance]\n\n[submit "Submit message"]'),
