	(200, 3, '2026-03-11 13:54:01', '2026-03-11 12:54:01', '', 'cc7c7b_0476e1ba3e444d8599b75f18c1cb04b8~mv2.jpg', '', 'inherit', 'closed', 'closed', '', 'cc7c7b_0476e1ba3e444d8599b75f18c1cb04b8mv2-jpg', '', '', '2026-03-11 13:54:01', '2026-03-11 12:54:01', '', 0, 'https://feboko.com/wp-content/uploads/2026/03/cc7c7b_0476e1ba3e444d8599b75f18c1cb04b8mv2.jpg.avif', 0, 'attachment', 'image/avif', 0),
	(201, 3, '2026-03-11 13:54:02', '2026-03-11 12:54:02', '', 'cc7c7b_a13458d12c5747af9c93f1ab7db61b6e~mv2.png', '', 'inherit', 'closed', 'closed', '', 'cc7c7b_a13458d12c5747af9c93f1ab7db61b6emv2-png', '', '', '2026-03-11 13:54:02', '2026-03-11 12:54:02', '', 0, 'https://feboko.com/wp-content/uploads/2026/03/cc7c7b_a13458d12c5747af9c93f1ab7db61b6emv2.png.avif', 0, 'attachment', 'image/avif', 0),
